sub entities{
local($_)=@_;
s/<#e9>/&eacute;/g;
s/<#e1>/&aacute;/g;
s/<#f1>/&ntilde;/g;
s/<#e8>/&egrave;/g;
s/<#fc>/&uuml;/g;
s/<#f6>/&ouml;/g;
s/<#f1>/&ntilde;/g;
s/<#f3>/&oacute;/g;
s/<#ed>/&iacute;/g;
s/<#cb>/&Euml;/g;
$_;
}
sub strip_name{
local($_) = @_;
s/^([A-Z][-a-z]+) (X?[-a-z]+).*(subsp\.|ssp\.|var\.|f\.) ([-a-z]+).*/$1 $2 $3 $4/ ||
s/^([A-Z][a-z]+) ([x ]*[-a-z]+).*/$1 $2/;
s/ssp\./subsp./;
return ($_);
}
